from typing import List


def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a dp array to store the minimum costs
    dp = [[float('inf')] * 3 for _ in range(n)]
    # Base case: the cost of painting the first house
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp array for the first half of the houses
    for i in range(1, n // 2 + 1):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    # Calculate the minimum cost for the second half of the houses
    for i in range(n // 2, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3]
            )

    # Ensure that the current house does not match its mirrored house
    for j in range(3):
        dp[n - 1][j] = cost[n - 1][j] + min(
            (dp[n // 2 - 1][(j + 1) % 3], dp[n // 2 - 1][(j + 2) % 3]) + (1 if (n // 2 -1) % 3 == j else 0)
        )

    # The result is the minimum cost of painting all houses
    return min(dp[n - 1])

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers  # Track online status
    offline_until = [0] * numberOfUsers  # Track when users will be back online

    for event in sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1)):
        event_type, timestamp, detail = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(detail)
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            # Update online statuses before processing message
            for user_id in range(numberOfUsers):
                if timestamp >= offline_until[user_id]:
                    online_status[user_id] = True

            if detail == "HERE":
                # Mention all online users
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            elif detail == "ALL":
                # Mention all users
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            else:
                # Explicit mentions
                user_ids = detail.split()
                for user_id in user_ids:
                    if user_id.startswith("id"):
                        uid = int(user_id[2:])
                        mentions[uid] += 1

    return mentions

